import csv
import zoneinfo
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path

EXPONENT = {"USD": 2, "EUR": 2, "JPY": 0, "KWD": 3}

def round_half_up(x: Decimal) -> int:
    return int(x.quantize(Decimal('1'), rounding=ROUND_HALF_UP))

def to_minor(amount: str, currency: str) -> int:
    exp = EXPONENT[currency]
    return int(Decimal(amount) * (10 ** exp))

def canonical_merchant_id(raw: str) -> str:
    return raw.strip(" \t\r\n\v\f").upper()

def settlement_date(occurred_at: str, tz_name: str):
    utc = datetime.strptime(occurred_at, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
    local = utc.astimezone(zoneinfo.ZoneInfo(tz_name))
    return local.date()

class RateTable:
    def __init__(self, rows):
        import bisect
        self._dates, self._rates = {}, {}
        for r in rows:
            pair = (r["from_currency"], r["to_currency"])
            self._rates[(pair, r["date"])] = Decimal(r["rate"])
            self._dates.setdefault(pair, []).append(r["date"])
        for dates in self._dates.values():
            dates.sort()

    def lookup(self, from_ccy, to_ccy, on):
        import bisect
        pair = (from_ccy, to_ccy)
        if pair not in self._dates:
            raise LookupError(f"no rates for {from_ccy}->{to_ccy}")
        dates = self._dates[pair]
        i = bisect.bisect_right(dates, on.isoformat()) - 1
        if i < 0:
            raise LookupError(f"no {from_ccy}->{to_ccy} rate usable on or before {on.isoformat()}")
        return self._rates[(pair, dates[i])]

def convert(amount: str, currency: str, settle_ccy: str, rates: RateTable, on):
    if currency == settle_ccy:
        return to_minor(amount, currency)
    rate = rates.lookup(currency, settle_ccy, on)
    s = EXPONENT[settle_ccy]
    val = Decimal(amount) * rate * (10 ** s)
    return round_half_up(val)
